  NaturalServerDispatcher() = delete;
  static void Dispatch(::fidl::Server<::fuchsia_device::NameProvider>* impl, ::fidl::IncomingHeaderAndMessage&& msg,
                       internal::MessageStorageViewBase* storage_view,
                       ::fidl::Transaction* txn);

 private:
